  "help.committedPercent": "ಮರುಕಳಿಸುವ ಮತ್ತು ಸಕ್ರಿಯ ಮಾಸಿಕ ಬಿಲ್‌ಗಳಿಗೆ ಹೋಗುವ ನಿಮ್ಮ ಮಾಸಿಕ ಆದಾಯದ ಪಾಲು. ಹೆಚ್ಚಿನ% ಎಂದರೆ ಆಶ್ಚರ್ಯಗಳಿಗೆ ಕಡಿಮೆ ಸ್ಥಳ.",
