  "support.about": "ಸುಮಾರು CommitTrack",
  "support.aboutBody": "CommitTrack ಭಾರತೀಯ ಕುಟುಂಬಗಳಿಗೆ ಬಿಲ್‌ಗಳು, ಸಾಲ ನೀಡುವಿಕೆ ಮತ್ತು ಮಾಸಿಕ ಒತ್ತಡವನ್ನು ಟ್ರ್ಯಾಕ್ ಮಾಡಲು ಸಹಾಯ ಮಾಡುತ್ತದೆ. Tadsaya ಅಡಿಯಲ್ಲಿ SaaS ಕಂಪನಿ Daloy Tech ನಿರ್ಮಿಸಿದೆ.",
