  "notifications.enabledOk": "ಬ್ರೌಸರ್ ಎಚ್ಚರಿಕೆಗಳನ್ನು ಸಕ್ರಿಯಗೊಳಿಸಲಾಗಿದೆ. ಅಪ್ಲಿಕೇಶನ್ ಮುಚ್ಚಿದಾಗ ಎಚ್ಚರಿಕೆಗಳಿಗಾಗಿ ಹೋಮ್ ಸ್ಕ್ರೀನ್‌ಗೆ ಅಪ್ಲಿಕೇಶನ್ ಸೇರಿಸಿ.",
  "notifications.deniedErr": "ಬ್ರೌಸರ್ ಸೆಟ್ಟಿಂಗ್‌ಗಳಲ್ಲಿ ನಿರ್ಬಂಧಿಸಲಾಗಿದೆ. ಈ ಸೈಟ್‌ಗಾಗಿ ಅಧಿಸೂಚನೆಗಳನ್ನು ಅನುಮತಿಸಿ, ನಂತರ ಮತ್ತೆ ಪ್ರಯತ್ನಿಸಿ.",
  "notifications.testOk": "ನಿಮ್ಮ ಸಿಸ್ಟಂ ಅಧಿಸೂಚನೆ ಫಲಕ ಮತ್ತು ಅಪ್ಲಿಕೇಶನ್‌ನಲ್ಲಿನ ಬೆಲ್‌ಗೆ ಕಳುಹಿಸಲಾಗಿದೆ. ಅದನ್ನು ನೋಡಲು ಫೋನ್‌ನಲ್ಲಿ ಕೆಳಗೆ ಸ್ವೈಪ್ ಮಾಡಿ.",
  "notifications.testDenied": "ಅನುಮತಿ ನಿರಾಕರಿಸಲಾಗಿದೆ. ಬ್ರೌಸರ್ ಅಥವಾ OS ಸೆಟ್ಟಿಂಗ್‌ಗಳಲ್ಲಿ ಎಚ್ಚರಿಕೆಗಳನ್ನು ಸಕ್ರಿಯಗೊಳಿಸಿ.",
  "notifications.testUnsupported": "ಈ ಬ್ರೌಸರ್ ಅಧಿಸೂಚನೆಗಳನ್ನು ಬೆಂಬಲಿಸುವುದಿಲ್ಲ.",
  "notifications.testFail": "ಎಚ್ಚರಿಕೆಯನ್ನು ತೋರಿಸಲಾಗಲಿಲ್ಲ. ಅಪ್ಲಿಕೇಶನ್ ಅನ್ನು ಸ್ಥಾಪಿಸಿ (ಹೋಮ್ ಸ್ಕ್ರೀನ್‌ಗೆ ಸೇರಿಸಿ) ಅಥವಾ Chrome/Edge ಬಳಸಿ.",
  "notifications.testInApp": "ಪರೀಕ್ಷಾ ಜ್ಞಾಪನೆ - ಈ ಸಾಧನದಲ್ಲಿ ಅಧಿಸೂಚನೆಗಳು ಕಾರ್ಯನಿರ್ವಹಿಸುತ್ತಿವೆ.",
  "notifications.installHint": "ಟ್ರೇ ಎಚ್ಚರಿಕೆಗಳಿಗಾಗಿ: ಅಪ್ಲಿಕೇಶನ್ ಅನ್ನು ಸ್ಥಾಪಿಸಿ (ಹೋಮ್ ಸ್ಕ್ರೀನ್‌ಗೆ ಸೇರಿಸಿ), ಅಧಿಸೂಚನೆಗಳನ್ನು ಅನುಮತಿಸಿ ಮತ್ತು ಜ್ಞಾಪನೆಗಳನ್ನು ಆನ್ ಮಾಡಿ. ನೀವು ಅಪ್ಲಿಕೇಶನ್ ಅನ್ನು ತೊರೆದಾಗ ಅಥವಾ ಪ್ರತಿ ಕೆಲವು ಗಂಟೆಗಳಿಗೊಮ್ಮೆ (Android/Chrome) ಬಾಕಿ ಇರುವ ಮತ್ತು ಮಿತಿಮೀರಿದ ಬಿಲ್‌ಗಳು ಸೂಚಿಸುತ್ತವೆ. iPhone ಗೆ ಹೋಮ್-ಸ್ಕ್ರೀನ್ ಅಪ್ಲಿಕೇಶನ್ ಐಕಾನ್ ಅಗತ್ಯವಿದೆ - Safari ಟ್ಯಾಬ್‌ಗಳು ಮಾತ್ರ ಹಿನ್ನೆಲೆ-ಅಧಿಸೂಚನೆ ಮಾಡಲಾಗುವುದಿಲ್ಲ.",
