  "privacy.collectTitle": "ನಾವು ಏನು ಸಂಗ್ರಹಿಸುತ್ತೇವೆ",
  "privacy.collectBody": "ಹೆಸರು, ಇಮೇಲ್, ಮೊಬೈಲ್ ಸಂಖ್ಯೆ, ಮಾಸಿಕ ಆದಾಯ, PAN (ಐಚ್ಛಿಕ), ಹಣಕಾಸಿನ ಬದ್ಧತೆಗಳು, ಸಾಲ ನೀಡುವ ದಾಖಲೆಗಳು, ಮಾಸಿಕ ಸ್ನ್ಯಾಪ್‌ಶಾಟ್‌ಗಳನ್ನು ಪ್ರದರ್ಶಿಸಿ.",
  "privacy.whyTitle": "ನಾವು ಅದನ್ನು ಏಕೆ ಸಂಗ್ರಹಿಸುತ್ತೇವೆ",
  "privacy.whyBody": "ನಿಮ್ಮ ಹಣಕಾಸಿನ ಒತ್ತಡದ ಸ್ಕೋರ್, ಬದ್ಧತೆಗಳ ಹೊರೆ, ಬದುಕುಳಿಯುವ ರನ್ವೇ ಮತ್ತು ಸಾಲ ದಾಖಲೆಗಳನ್ನು ಲೆಕ್ಕಹಾಕಲು ಮಾತ್ರ. ಬೇರೆ ಉದ್ದೇಶವಿಲ್ಲ.",
  "privacy.whereTitle": "ಅದನ್ನು ಎಲ್ಲಿ ಸಂಗ್ರಹಿಸಲಾಗಿದೆ",
  "privacy.whereBody": "ಪ್ರಾಥಮಿಕವಾಗಿ ನಿಮ್ಮ ಸಾಧನದಲ್ಲಿ (ಸ್ಥಳೀಯ ಸಂಗ್ರಹಣೆ). ಕ್ಲೌಡ್ ಸಿಂಕ್ ಅನ್ನು ಸಕ್ರಿಯಗೊಳಿಸಿದಾಗ ಐಚ್ಛಿಕವಾಗಿ Supabase ನಲ್ಲಿ (ವಿಶ್ರಾಂತಿಯಲ್ಲಿ ಎನ್‌ಕ್ರಿಪ್ಟ್ ಮಾಡಲಾಗಿದೆ, ಪ್ರತಿ ಬಳಕೆದಾರರಿಗೆ ಪ್ರತ್ಯೇಕಿಸಲಾಗಿದೆ).",
  "privacy.notTitle": "ನಾವು ಏನು ಮಾಡುವುದಿಲ್ಲ",
  "privacy.notBody": "ನಾವು ನಿಮ್ಮ ಡೇಟಾವನ್ನು ಮಾರಾಟ ಮಾಡುವುದಿಲ್ಲ. ನಾವು ಕ್ರೆಡಿಟ್ ಬ್ಯೂರೋಗಳೊಂದಿಗೆ ಹಂಚಿಕೊಳ್ಳುವುದಿಲ್ಲ. ನಾವು ಜಾಹೀರಾತಿಗಾಗಿ ಡೇಟಾವನ್ನು ಬಳಸುವುದಿಲ್ಲ. Razorpay ಪಾವತಿಗಳನ್ನು ನಿಭಾಯಿಸುತ್ತದೆ - CommitTrack ನಿಮ್ಮ ಕಾರ್ಡ್ ವಿವರಗಳನ್ನು ಎಂದಿಗೂ ನೋಡುವುದಿಲ್ಲ.",
  "privacy.rightsTitle": "ನಿಮ್ಮ ಹಕ್ಕುಗಳು (DPDP ಕಾಯಿದೆ 2023)",
