  "insight.burden-danger": "EMI-ಶೈಲಿಯ ಹೊರೆಯು ಆದಾಯಕ್ಕೆ ಸಂಬಂಧಿಸಿದಂತೆ ಹೆಚ್ಚಿನ ಶ್ರೇಣಿಯಲ್ಲಿದೆ. ಸಾಧ್ಯವಾದರೆ ಹೊಸ ಬದ್ಧತೆಗಳನ್ನು ಮುಂದೂಡಿ.",
  "insight.burden-risk": "ಆದಾಯಕ್ಕೆ ಹೋಲಿಸಿದರೆ ಮಾಸಿಕ ಬಿಲ್ ಹೊರೆಯನ್ನು ಹೆಚ್ಚಿಸಲಾಗಿದೆ - ವಿವೇಚನಾ ವೆಚ್ಚವನ್ನು ಪರಿಶೀಲಿಸಿ.",
  "insight.subs-weight": "ಚಂದಾದಾರಿಕೆಗಳು ನಿಮ್ಮ ಬೇಸ್‌ಲೈನ್‌ಗೆ ಸರಿಸುಮಾರು {amount}/mo ಅನ್ನು ಸೇರಿಸುತ್ತವೆ - ಮರುಕಳಿಸುವ ವೆಚ್ಚಗಳು ಕಾಲಾನಂತರದಲ್ಲಿ ಸಂಗ್ರಹಗೊಳ್ಳುತ್ತವೆ.",
  "insight.open-up": "ಹಿಂದಿನ ಸ್ನ್ಯಾಪ್‌ಶಾಟ್‌ಗೆ ಹೋಲಿಸಿದರೆ ಓಪನ್ ಬಿಲ್ ಬ್ಯಾಲೆನ್ಸ್ ಹೆಚ್ಚಾಗಿದೆ ({fromMonth} → {toMonth}).",
  "insight.pressure-down": "ಹಿಂದಿನ ತಿಂಗಳ ಸ್ನ್ಯಾಪ್‌ಶಾಟ್‌ಗೆ ಹೋಲಿಸಿದರೆ ನೀವು ತೆರೆದ ಬಿಲ್ ಒತ್ತಡವನ್ನು ಕಡಿಮೆ ಮಾಡಿದ್ದೀರಿ.",
  "insight.multi-overdue": "{count} ಐಟಂಗಳು ಮಿತಿಮೀರಿದವು - ಅವುಗಳನ್ನು ಮೊದಲು ತೆರವುಗೊಳಿಸುವುದು ಸಾಮಾನ್ಯವಾಗಿ ನೇರವಾಗಿ ಒತ್ತಡವನ್ನು ಕಡಿಮೆ ಮಾಡುತ್ತದೆ.",
  "insight.paying-habit": "ನೀವು ಈ ತಿಂಗಳ ಪಾವತಿಗಳಲ್ಲಿ {amount} ಅನ್ನು ರೆಕಾರ್ಡ್ ಮಾಡಿದ್ದೀರಿ - ಸ್ಥಿರ ಪಾವತಿಗಳು ಹಣಕಾಸಿನ ರನ್‌ವೇಯನ್ನು ಸುಧಾರಿಸುತ್ತದೆ.",
  "insight.overlap-week": "ನೀವು ಈ ವಾರ {count} ಬಾಕಿಗಳನ್ನು ಹೊಂದಿರುವಿರಿ (≈{total} ಒಟ್ಟು)—ಸಾಧ್ಯವಾದರೆ ದಿಗ್ಭ್ರಮೆಗೊಳಿಸುವ ಪಾವತಿಗಳು.",
  "insight.forecast-crunch-negative": "ನೀವು {month} ಸುಮಾರು ಋಣಾತ್ಮಕ ಉಚಿತ ನಗದು ಎದುರಿಸಬಹುದು (ಬಾಕಿಗಳು ಆ ತಿಂಗಳ ಆದಾಯವನ್ನು ಮೀರುತ್ತದೆ).",
  "insight.forecast-crunch-tight": "ಸುಮಾರು {month} ನಗದನ್ನು ಸೀಮಿತಗೊಳಿಸಬಹುದು — ಅಂದಾಜು ಬಾಕಿಗಳ ನಂತರ ≈{free} ಮಾತ್ರ ಉಚಿತ.",
  "insight.subs-yearly": "ಪ್ರಸ್ತುತ ದರಗಳಲ್ಲಿ ನಿಮ್ಮ ಚಂದಾದಾರಿಕೆಗಳು ಸುಮಾರು {amount}/ವರ್ಷಕ್ಕೆ ವೆಚ್ಚವಾಗಬಹುದು.",
  "insight.emi-pct": "EMIs ನಿಮ್ಮ ಹೇಳಲಾದ ಮಾಸಿಕ ಆದಾಯದ ಸುಮಾರು {percent}% ಅನ್ನು ಬಳಸುತ್ತದೆ - ಹೊಸ ಸಾಲದೊಂದಿಗೆ ಎಚ್ಚರಿಕೆಯಿಂದಿರಿ.",
  "insight.txn-delivery-dependency": "ಈ ವಾರ ಆಹಾರ ವಿತರಣಾ ವೆಚ್ಚವು ದೊಡ್ಡ ಪಾಲು - ಅವಲಂಬನೆಯು ಸದ್ದಿಲ್ಲದೆ ಬೆಳೆಯಬಹುದು.",
  "insight.txn-health-spend-week": "ಆರೋಗ್ಯ-ಸಂಬಂಧಿತ ಖರ್ಚುಗಳು ಈ ವಾರ ಏರಿದೆ - ಬದುಕುಳಿಯುವ ವೆಚ್ಚಗಳು ಅಲ್ಪಾವಧಿಯ ಹಣವನ್ನು ಬಿಗಿಗೊಳಿಸಬಹುದು.",
  "insight.txn-discretionary-rise": "ಹಿಂದಿನ ತಿಂಗಳಿಗೆ ಹೋಲಿಸಿದರೆ ದೈನಂದಿನ ವಿವೇಚನೆಯ ಖರ್ಚು ಹೆಚ್ಚಾಗಿದೆ.",
  "insight.txn-lifestyle-stack": "ಇತ್ತೀಚಿನ ಜೀವನಶೈಲಿ ಖರ್ಚುಗಳೊಂದಿಗೆ ಮರುಕಳಿಸುವ {merchant} ವೆಚ್ಚಗಳ ಸ್ಟ್ಯಾಕ್ - ವಿಮರ್ಶೆ ಅತಿಕ್ರಮಣ.",
  "insight.txn-small-leaks": "ಈ ವಾರದ ಹಲವಾರು ಸಣ್ಣ ಖರೀದಿಗಳು ಮಾಸಿಕ ನಮ್ಯತೆಯನ್ನು ನಿಧಾನವಾಗಿ ಕಡಿಮೆ ಮಾಡಬಹುದು.",
  "insight.txn-daily-budget-cap": "ಬಿಲ್‌ಗಳು ಆದಾಯದ ~{percent}% ಅನ್ನು ಬಳಸುತ್ತವೆ - ತಿಂಗಳ ಉಳಿದ ಅವಧಿಗೆ ಜೀವನಶೈಲಿಯ ಖರ್ಚುಗಳ ಮೇಲೆ ಸುಮಾರು {cap}/ದಿನದ ಗುರಿ.",
  "insight.txn-daily-budget-room": "ಬಾಕಿಯ ನಂತರ, ಈ ತಿಂಗಳ ಉಳಿದ ಭಾಗಕ್ಕೆ ಸುಮಾರು {amount}/ದಿನಕ್ಕೆ ಹೊಂದಿಕೊಳ್ಳುತ್ತದೆ.",
  "insight.txn-recurring-growth-high": "ಪುನರಾವರ್ತಿತ ಐಚ್ಛಿಕ ಖರ್ಚು ನಿಧಾನವಾಗಿ ಹೆಚ್ಚುತ್ತಿದೆ - ಸಣ್ಣ ಪುನರಾವರ್ತನೆಗಳು ನಮ್ಯತೆಯನ್ನು ಕಡಿಮೆ ಮಾಡಬಹುದು.",
  "insight.txn-recurring-growth": "ಇತ್ತೀಚಿನ ತಿಂಗಳುಗಳಲ್ಲಿ ಮರುಕಳಿಸುವ ಬಾಧ್ಯತೆಗಳು ಸುಮಾರು {percent}% ನಷ್ಟು ಬೆಳೆದಿದೆ.",
  "insight.txn-under-pressure": "ಬಾಧ್ಯತೆಯ ಒತ್ತಡವು ಈಗಾಗಲೇ ಹೆಚ್ಚಿರುವಾಗ ವಿವೇಚನೆಯ ದೈನಂದಿನ ಖರ್ಚು ಮುಂದುವರಿಯುತ್ತದೆ.",
  "insight.txn-rhythm-unsafe": "ಮುಂಬರುವ ವಾರವು ದಟ್ಟವಾದ ದಿನಾಂಕಗಳನ್ನು ಹೊಂದಿದೆ - ಹೆಚ್ಚಿನ ಅಪಾಯದ ನಗದು ವಿಂಡೋ ಎಂದು ಪರಿಗಣಿಸಿ.",
  "insight.txn-rhythm-overlap": "ಮುಂದಿನ ವಾರದಲ್ಲಿ ಹಲವಾರು ಕಟ್ಟುಪಾಡುಗಳು ಅತಿಕ್ರಮಿಸುತ್ತವೆ - ಅವುಗಳು ಪೇರಿಸುವ ಮೊದಲು ಹಣವನ್ನು ಯೋಜಿಸಿ.",
  "insight.txn-rhythm-lifestyle": "ಇತ್ತೀಚಿನ ದಿನನಿತ್ಯದ ನೇರ ಜೀವನಶೈಲಿ-ಭಾರೀ ಖರ್ಚುಗಳು - ವಿವೇಚನೆಯ ಹರಿವು ನಮ್ಯತೆಯನ್ನು ಕಡಿಮೆ ಮಾಡಬಹುದು.",
  "insight.feed-restaurant-week": "ಈ ವಾರ ರೆಸ್ಟೋರೆಂಟ್ ಮತ್ತು ಡೆಲಿವರಿ ವೆಚ್ಚವನ್ನು ಹೆಚ್ಚಿಸಲಾಗಿದೆ.",
  "insight.feed-medical-month": "ವೈದ್ಯಕೀಯ ವೆಚ್ಚಗಳು ಈ ತಿಂಗಳು ಸಾಮಾನ್ಯಕ್ಕಿಂತ ಹೆಚ್ಚಾಗಿರುತ್ತದೆ.",
  "narrative.strength.repaymentRhythm": "ಇತ್ತೀಚಿನ ತಿಂಗಳುಗಳಲ್ಲಿ ಸ್ಥಿರ ಮರುಪಾವತಿಯ ಲಯ",
  "narrative.strength.billHealth": "ಒಟ್ಟಾರೆ ಬಿಲ್ ಆರೋಗ್ಯವು ನಿರ್ವಹಿಸಬಹುದಾದಂತೆ ಕಾಣುತ್ತದೆ",
  "narrative.strength.commitmentsRoom": "ಮಾಸಿಕ ಬದ್ಧತೆಗಳು ನಿಮ್ಮ ಬಜೆಟ್‌ನಲ್ಲಿ ಸಮಂಜಸವಾದ ಜಾಗವನ್ನು ಬಿಡುತ್ತವೆ",
