  "narrative.strength.recurringStable": "ಮರುಕಳಿಸುವ ಖರ್ಚು ಇತ್ತೀಚೆಗೆ ತೀವ್ರವಾಗಿ ಏರಿಕೆಯಾಗಿಲ್ಲ",
  "narrative.weakness.overdueOne": "ಒಂದು ಮಿತಿಮೀರಿದ ಬಿಲ್ ಗಮನಹರಿಸಬೇಕು",
  "narrative.weakness.overdueMany": "{count} ಮಿತಿಮೀರಿದ ಬಿಲ್‌ಗಳು ಒತ್ತಡವನ್ನು ಸೇರಿಸುತ್ತವೆ",
