  "stability.goalBalance.stagger": "ಬಹು ಗುರಿಗಳು ಸಕ್ರಿಯವಾಗಿವೆ - ದಿಗ್ಭ್ರಮೆಗೊಳಿಸುವ ಗುರಿಗಳು ಆದ್ದರಿಂದ ಒಂದು ಮೈಲಿಗಲ್ಲು ಇತರರ ಮೇಲೆ ಪ್ರಗತಿಯನ್ನು ಕಡಿಮೆ ಮಾಡುವುದಿಲ್ಲ.",
  "insight.goal-overlap": "ನೀವು {count} ಗುರಿಗಳನ್ನು ಟ್ರ್ಯಾಕ್ ಮಾಡುತ್ತಿದ್ದೀರಿ ಆದರೆ ಮಾಸಿಕ ಬಾಕಿಗಳು ಆದಾಯದ ಹೆಚ್ಚಿನ ಪಾಲನ್ನು ಬಳಸುತ್ತವೆ - ಎಲ್ಲಾ ರಂಗಗಳಲ್ಲಿ ಪ್ರಗತಿಯು ನಿಧಾನವಾಗಬಹುದು.",
  "insight.goal-edu-wedding": "ಶಿಕ್ಷಣ ಮತ್ತು ಮದುವೆ ಅಥವಾ ಈವೆಂಟ್ ಗುರಿಗಳಿಗೆ ಸ್ಪಷ್ಟ ಮಾಸಿಕ ಸ್ಲೈಸ್ ಅಗತ್ಯವಿದೆ - ಯಾವುದು ಮೊದಲು ಬರುತ್ತದೆ ಎಂದು ಪರಿಗಣಿಸಿ.",
  "insight.goal-debt-save": "ಸಾಲವನ್ನು ಪಾವತಿಸುವುದು ಮತ್ತು ಉಳಿತಾಯವನ್ನು ಏಕಕಾಲದಲ್ಲಿ ನಿರ್ಮಿಸುವುದು ಸೀಮಿತ ಉಚಿತ ನಗದು ಮೇಲೆ ಕಷ್ಟ - ಒಂದು ಉದ್ದೇಶಕ್ಕೆ ಆದ್ಯತೆ ನೀಡಿ.",
