  "profileHub.scoreWhy.pressure.what": "ನಿಮ್ಮ ಆದಾಯದ ಎಷ್ಟು ಮೊತ್ತವನ್ನು ಬಿಲ್‌ಗಳು ಮತ್ತು ಮಿತಿಮೀರಿದ ಐಟಂಗಳಲ್ಲಿ ಲಾಕ್ ಮಾಡಲಾಗಿದೆ ಎಂಬುದನ್ನು ಅಳೆಯುತ್ತದೆ.",
  "profileHub.scoreWhy.pressure.high": "ಆದಾಯಕ್ಕೆ ಸಂಬಂಧಿಸಿದಂತೆ ಅನೇಕ ಬಿಲ್‌ಗಳು ಶೀಘ್ರದಲ್ಲೇ ಅಥವಾ ಮಿತಿಮೀರಿದ ಬಾಕಿಯಿದೆ.",
  "profileHub.scoreWhy.pressure.mid": "ಆದಾಯದ ಗಮನಾರ್ಹ ಪಾಲು ಮರುಕಳಿಸುವ ಬಾಕಿಗಳಿಗೆ ಹೋಗುತ್ತದೆ.",
  "profileHub.scoreWhy.pressure.low": "ಇದೀಗ ಆದಾಯಕ್ಕೆ ಸಂಬಂಧಿಸಿದಂತೆ ಬಿಲ್‌ಗಳನ್ನು ನಿರ್ವಹಿಸಬಹುದಾಗಿದೆ.",
  "profileHub.scoreWhy.health.what": "ಬಿಲ್ ಹೊರೆ, ಪಾವತಿ ಪದ್ಧತಿ, ಉಳಿತಾಯ ಬಫರ್ ಮತ್ತು ಸಾಲದ ಪ್ರವೃತ್ತಿಯನ್ನು ಸಂಯೋಜಿಸುತ್ತದೆ.",
  "profileHub.scoreWhy.health.low": "ಹೊರೆ, ಬಫರ್ ಅಥವಾ ಪಾವತಿಯ ಸ್ಥಿರತೆಯ ದುರ್ಬಲತೆಯು ಇದನ್ನು ಕೆಳಕ್ಕೆ ಎಳೆಯುತ್ತಿದೆ.",
  "profileHub.scoreWhy.health.mid": "ಕೆಲವು ಪ್ರದೇಶಗಳಲ್ಲಿ ಘನ - ಕೆಲವು ಅಭ್ಯಾಸಗಳು ಅಥವಾ ಬಫರ್‌ಗಳು ಇದನ್ನು ಎತ್ತಬಹುದು.",
  "profileHub.scoreWhy.health.good": "ಒಟ್ಟಾರೆ ಅಭ್ಯಾಸಗಳು ಮತ್ತು ಬಫರ್‌ಗಳು ಆರೋಗ್ಯಕರವಾಗಿ ಕಾಣುತ್ತವೆ.",
  "profileHub.scoreWhy.runway.what": "ಆದಾಯವನ್ನು ವಿರಾಮಗೊಳಿಸಿದರೆ (ದ್ರವ ಉಳಿತಾಯ + ಉಚಿತ ನಗದು) ತಿಂಗಳವರೆಗೆ ನೀವು ಅಗತ್ಯ ವಸ್ತುಗಳನ್ನು ಕವರ್ ಮಾಡಬಹುದು.",
  "profileHub.scoreWhy.runway.critical": "ತುಂಬಾ ತೆಳುವಾದ ಕುಶನ್ - ಒಂದು ಆದಾಯದ ಆಘಾತವನ್ನು ಹೀರಿಕೊಳ್ಳಲು ಕಷ್ಟವಾಗುತ್ತದೆ.",
  "profileHub.scoreWhy.runway.thin": "ಆರಾಮದಾಯಕ 3-6 ತಿಂಗಳ ಮೀಸಲು ಕೆಳಗೆ.",
  "profileHub.scoreWhy.runway.ok": "ಸದ್ಯಕ್ಕೆ ರನ್‌ವೇ ಸುರಕ್ಷಿತ ವ್ಯಾಪ್ತಿಯಲ್ಲಿದೆ.",
  "profileHub.scoreWhy.flexibility.what": "ನಿಗದಿತ ಮಾಸಿಕ ಬಾಕಿಯ ನಂತರ ನೀವು ಎಷ್ಟು ಕೊಠಡಿಯನ್ನು ಹೊಂದಿದ್ದೀರಿ.",
  "profileHub.scoreWhy.flexibility.low": "ಹೆಚ್ಚಿನ ಆದಾಯವು ಈಗಾಗಲೇ ಮರುಕಳಿಸುವ ಬಿಲ್‌ಗಳಿಗೆ ಬದ್ಧವಾಗಿದೆ.",
  "profileHub.scoreWhy.flexibility.ok": "ನೀವು ಪ್ರತಿ ತಿಂಗಳು ಅರ್ಥಪೂರ್ಣ ಉಚಿತ ಹಣವನ್ನು ಉಳಿಸಿಕೊಳ್ಳುತ್ತೀರಿ.",
  "profileHub.scoreWhy.debt.what": "EMI ಮತ್ತು ಸಾಲ ಪಾವತಿಗಳು ಮಾಸಿಕ ಆದಾಯದ ಪಾಲು.",
  "profileHub.scoreWhy.debt.high": "EMI ಲೋಡ್ ಭಾರವಾಗಿದೆ - ಹೊಸ ಸಾಲಗಳು ನಗದು ಹರಿವನ್ನು ತಗ್ಗಿಸುತ್ತವೆ.",
  "profileHub.scoreWhy.debt.ok": "ಸಾಲ ಪಾವತಿಗಳು ನಿರ್ವಹಿಸಬಹುದಾದ ಬ್ಯಾಂಡ್‌ನಲ್ಲಿವೆ.",
  "profileHub.scoreWhy.lending.what": "ಸಾಲ ನೀಡುವಾಗ ನೀವು ನೀಡಿದ ಅಥವಾ ಸ್ವೀಕರಿಸಿದ ಸಮಯಕ್ಕೆ ಮರುಪಾವತಿಯನ್ನು ಟ್ರ್ಯಾಕ್ ಮಾಡುತ್ತದೆ.",
  "profileHub.scoreWhy.lending.empty": "ಇನ್ನೂ ಯಾವುದೇ ಸಾಲ ನಮೂದುಗಳಿಲ್ಲ - ಈ ಸ್ಕೋರ್ ಅನ್ನು ನಿರ್ಮಿಸಲು ಡೀಲ್‌ಗಳನ್ನು ಸೇರಿಸಿ ಮತ್ತು ಮರುಪಾವತಿಯನ್ನು ಲಾಗ್ ಮಾಡಿ.",
  "profileHub.scoreWhy.lending.low": "ತಡವಾದ ಅಥವಾ ಭಾಗಶಃ ಮರುಪಾವತಿಗಳು ನಂಬಿಕೆಯನ್ನು ಕಡಿಮೆಗೊಳಿಸುತ್ತವೆ.",
  "profileHub.scoreWhy.lending.ok": "ಮರುಪಾವತಿ ಇತಿಹಾಸವು ವಿಶ್ವಾಸಾರ್ಹವಾಗಿ ಕಾಣುತ್ತದೆ.",
  "profileHub.scoreFix.pressure.clearOverdue": "ಮಿತಿಮೀರಿದ ಬಿಲ್‌ಗಳನ್ನು ಮೊದಲು ತೆರವುಗೊಳಿಸಿ - ಅವರು ಈ ಸ್ಕೋರ್‌ಗೆ ಹೆಚ್ಚು ಹಾನಿ ಮಾಡುತ್ತಾರೆ.",
  "profileHub.scoreFix.pressure.trimSubscriptions": "ನೀವು ವಿರಾಮಗೊಳಿಸಬಹುದಾದ ಚಂದಾದಾರಿಕೆಗಳು ಮತ್ತು ಐಚ್ಛಿಕ EMIಗಳನ್ನು ಪರಿಶೀಲಿಸಿ.",
  "profileHub.scoreFix.pressure.payOnTime": "ಒತ್ತಡವನ್ನು ಸ್ಥಿರಗೊಳಿಸಲು ಈ ತಿಂಗಳು ನಿಗದಿತ ದಿನಾಂಕಗಳ ಮೊದಲು ಪಾವತಿಸಿ.",
  "profileHub.scoreFix.runway.buildReserve": "ಪ್ರತಿ ಸಂಬಳದ ದಿನಕ್ಕೆ ದ್ರವ ಉಳಿತಾಯಕ್ಕೆ ನಿಗದಿತ ಮೊತ್ತವನ್ನು ಸರಿಸಿ.",
  "profileHub.scoreFix.runway.reduceBurn": "ರನ್‌ವೇಯನ್ನು ವಿಸ್ತರಿಸಲು ಅನಿವಾರ್ಯವಲ್ಲದ ಮರುಕಳಿಸುವ ಬಿಲ್‌ಗಳನ್ನು ಟ್ರಿಮ್ ಮಾಡಿ.",
  "profileHub.scoreFix.health.reduceBurden": "ಹೆಚ್ಚಿನ ಹೊರೆಯ ಬದ್ಧತೆಗಳನ್ನು ಕಡಿಮೆ ಮಾಡಿ ಅಥವಾ ಮರುಹೊಂದಿಸಿ.",
  "profileHub.scoreFix.health.buildBuffer": "ದ್ರವ ಉಳಿತಾಯದಲ್ಲಿ 3-6 ತಿಂಗಳ ವೆಚ್ಚಗಳನ್ನು ಗುರಿಪಡಿಸಿ.",
  "profileHub.scoreFix.health.payOnTime": "ಪಾವತಿ ಸ್ಟ್ರೀಕ್ ಅನ್ನು ಇರಿಸಿಕೊಳ್ಳಿ - ಪ್ರತಿ ಬಿಲ್ ಪಾವತಿಯನ್ನು ಲಾಗ್ ಮಾಡಿ.",
  "profileHub.scoreFix.health.reduceDebt": "ಮೊದಲು ಅತ್ಯಧಿಕ-ಬಡ್ಡಿ ಬ್ಯಾಲೆನ್ಸ್‌ನಲ್ಲಿ ಚಿಪ್ ಮಾಡಿ.",
  "profileHub.scoreFix.health.keepGoing": "Keep current habits — you're on track.",
